<div class="page-head"><div><h1>Domains</h1><p class="muted">All custom domains mapped to shops. Each must be added to this hosting (addon/parked domain) and point its DNS here. See README → "Custom domains".</p></div></div>
<div class="table-wrap"><table class="table"><thead><tr><th>Domain</th><th>Shop</th><th>Shop status</th><th>Primary</th><th>DNS</th><th>SSL</th><th>Hosting</th><th>Last check</th></tr></thead><tbody>
<?php foreach ($domains as $d): ?><tr><td class="strong"><?= e($d['domain']) ?></td><td><a href="/superadmin/shops/<?= (int) $d['shop_id'] ?>/"><?= e($d['shop_name']) ?></a></td><td><?= status_badge($d['status']) ?></td><td><?= $d['is_primary'] ? '★' : '' ?></td><td><span class="badge badge-<?= $d['dns_status'] === 'ok' ? 'ok' : 'warn' ?>"><?= e($d['dns_status']) ?></span></td><td><span class="badge badge-<?= $d['ssl_status'] === 'ok' ? 'ok' : 'warn' ?>"><?= e($d['ssl_status']) ?></span></td><td><?= e($d['hosting_status']) ?></td><td class="small"><?= e(fmt_date($d['last_checked_at'], true)) ?></td></tr><?php endforeach ?>
<?php if (!$domains): ?><tr><td colspan="8" class="empty-cell">No custom domains yet.</td></tr><?php endif ?>
</tbody></table></div>
